CREATE TABLE IF NOT EXISTS bots (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, code TEXT, key_hash TEXT, house INTEGER NOT NULL DEFAULT 0, created INTEGER);
CREATE TABLE IF NOT EXISTS preds (bot INTEGER NOT NULL, sym TEXT NOT NULL, tf TEXT NOT NULL, t0 INTEGER NOT NULL, dir INTEGER NOT NULL, PRIMARY KEY (bot, sym, tf, t0));
CREATE INDEX IF NOT EXISTS preds_due ON preds (sym, tf, t0);
CREATE TABLE IF NOT EXISTS agg (bot INTEGER NOT NULL, tf TEXT NOT NULL, t0 INTEGER NOT NULL, n INTEGER NOT NULL, ok INTEGER NOT NULL, gross REAL NOT NULL, PRIMARY KEY (bot, tf, t0));
