CREATE TABLE IF NOT EXISTS cfg (k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, sub TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', created INTEGER);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, user INTEGER NOT NULL, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS used (id TEXT PRIMARY KEY, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ustats (user INTEGER NOT NULL, tf TEXT NOT NULL, n INTEGER NOT NULL, ok INTEGER NOT NULL, PRIMARY KEY (user, tf));
CREATE TABLE IF NOT EXISTS news (url TEXT PRIMARY KEY, src TEXT NOT NULL, lang TEXT NOT NULL, title TEXT NOT NULL, en TEXT, fr TEXT, ts INTEGER NOT NULL, coins TEXT NOT NULL DEFAULT ',,', tr INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS news_ts ON news (ts);
CREATE TABLE IF NOT EXISTS feedlog (src TEXT PRIMARY KEY, at INTEGER, status INTEGER, n INTEGER);
INSERT OR IGNORE INTO bots (name, code, house, created) VALUES ('big5','big5',1,1794873600),('news5','news5',1,1794873600);
CREATE TABLE IF NOT EXISTS snap (k TEXT PRIMARY KEY, v TEXT, at INTEGER, status INTEGER, tried INTEGER);
CREATE TABLE IF NOT EXISTS hist (k TEXT NOT NULL, t INTEGER NOT NULL, x REAL NOT NULL, PRIMARY KEY (k, t));
